const student = $input.first().json;
const lessons = Array.isArray(student.recent_lessons) ? student.recent_lessons : [];
const latest = lessons[0] || {};

const parts = [student.subject, student.current_topic, latest.next_assignment, latest.notes].filter(Boolean);
const queryText = parts.join(' - ') || (student.subject || 'مادة عامة');

return { json: { ...student, queryText } };

const student = $('Build Search Query Text').item.json;
const cfg = $('Decode JWT & Config').item.json;
const raw = $input.first().json;
const values = raw && raw.embedding && Array.isArray(raw.embedding.values) ? raw.embedding.values : null;

return {
  json: {
    ...student,
    teacherId: cfg.teacherId,
    studentId: cfg.studentId,
    topK: cfg.topK,
    embeddingLiteral: values ? ('[' + values.join(',') + ']') : null
  }
};

const student = $('Parse Query Embedding').item.json;
const chunks = $input.all().map(i => i.json).filter(c => c.content);

const lessons = Array.isArray(student.recent_lessons) ? student.recent_lessons : [];
const notes = Array.isArray(student.notes) ? student.notes : [];

const lessonsText = lessons.length
  ? lessons.map((l) => {
      const date = (l.lesson_date || '').toString().substring(0, 10);
      const parts = [];
      if (l.lesson_content) parts.push(`المحتوى: ${l.lesson_content}`);
      if (l.memorization) parts.push(`الحفظ: ${l.memorization}`);
      if (l.recitation) parts.push(`الأداء الشفهي: ${l.recitation}`);
      if (l.performance) parts.push(`الأداء العام: ${l.performance}`);
      if (l.notes) parts.push(`ملاحظات: ${l.notes}`);
      if (l.next_assignment) parts.push(`المهمة القادمة: ${l.next_assignment}`);
      if (l.homework) parts.push(`الواجب: ${l.homework}`);
      return `[حصة ${date}] ${parts.join(' - ') || 'بدون تفاصيل مسجّلة'}`;
  }).join('\n')
  : 'لا يوجد سجل حصص سابقة بعد.';

const notesText = notes.length ? notes.map(n => `- ${n.note}`).join('\n') : 'لا توجد ملاحظات مسجّلة عن هذا الطالب.';

const sourcesText = chunks.length
  ? chunks.map((c, i) => `[مصدر ${i + 1}] من كتاب "${c.book_title}"${c.chapter_title ? ' - ' + c.chapter_title : ''}${c.page_number ? ' - صفحة ' + c.page_number : ''}:\n${c.content}`).join('\n\n')
  : 'لا توجد مصادر (كتب) مرتبطة بهذا الطالب بعد.';

const prompt = `أنتِ مساعد بيجهّز خطة حصة سريعة لمعلم قبل ما يدخل يشرح لطالبه "${student.name}".

== بيانات الطالب ==
المادة: ${student.subject || 'غير محددة'}
الموضوع الحالي: ${student.current_topic || 'غير محدد'}

== سجل آخر الحصص ==
${lessonsText}

== ملاحظات المعلم عن الطالب ==
${notesText}

== مقاطع من مصادر المعلم (كتب/مذكرات) ذات صلة ==
${sourcesText}

جهّز خطة حصة مختصرة وعملية بالاعتماد على المصادر أعلاه قدر الإمكان (واستشهد برقم المصدر [مصدر N] لو استخدمتيه)، وأعد الناتج بصيغة JSON فقط بالشكل التالي بالظبط، بالعربية:
{
  "goal": "هدف الحصة في جملة واحدة",
  "review": "إيه اللي يستاهل مراجعته الأول",
  "teaching_method": "طريقة شرح مقترحة",
  "exercise": "تمرين مقترح للطالب",
  "homework": "واجب مقترح",
  "watch_point": "نقطة تحتاج انتباه خاص مع هذا الطالب تحديدًا"
}`;

return {
  json: {
    teacherId: student.teacherId,
    sources: chunks.map(c => ({ book_id: c.book_id, book_title: c.book_title, chapter: c.chapter_title, page: c.page_number })),
    geminiRequestBody: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: { temperature: 0.4, maxOutputTokens: 1200, responseMimeType: 'application/json' }
    }
  }
};

const prev = $('Build Lesson Prep Prompt').item.json;
const raw = $input.first().json;

function fail(message) {
  return { json: { success: false, message } };
}

if (raw.error) {
  return fail('تعذّر تجهيز الحصة، من فضلك حاولي مرة أخرى.');
}

const candidate = raw.candidates && raw.candidates[0];
const text = candidate && candidate.content && candidate.content.parts && candidate.content.parts[0] && candidate.content.parts[0].text;
if (!text) {
  return fail('تعذّر توليد خطة مناسبة لهذه الحصة.');
}

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  return fail('تعذّر فهم استجابة تجهيز الحصة.');
}

return {
  json: {
    success: true,
    plan: {
      goal: parsed.goal || '',
      review: parsed.review || '',
      teaching_method: parsed.teaching_method || '',
      exercise: parsed.exercise || '',
      homework: parsed.homework || '',
      watch_point: parsed.watch_point || ''
    },
    sources: prev.sources
  }
};

